CREATE ROLE IF NOT EXISTS ANALYTICS_READER;
CREATE ROLE IF NOT EXISTS ANALYST;
-- add least-privilege grants

-- Network policy example
CREATE NETWORK POLICY corp_only
  ALLOWED_IP_LIST = ('203.0.113.0/24');

SELECT *
FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY
WHERE START_TIME >= DATEADD('hour', -1, CURRENT_TIMESTAMP());

CREATE FILE FORMAT IF NOT EXISTS FF_CSV
  TYPE = CSV
  SKIP_HEADER = 1;

CREATE STAGE IF NOT EXISTS LOAD_STAGE
  FILE_FORMAT = FF_CSV;

-- COPY INTO target table

WITH src AS (
  SELECT PARSE_JSON('{"items":[{"sku":"A"},{"sku":"B"}]}') AS payload
)
SELECT f.value:sku::STRING AS sku
FROM src, LATERAL FLATTEN(INPUT => payload:items) f;
